def convert_parameters_to_provision_delta_plan_payload(param_dit):
    """

    :param param_dit: like
                      {'para1/0/sub1':'value0-1',
                       'para1/0/sub2':'value0-2',
                       'para1/1/sub1':'value1-1',
                       'para2/0/sub1':'value2-1',
                       'para2/1/sub1':'value2-2',
                       'para3':'value3'}
    :return: {'para1': [{'sub1': 'value0-1', 'sub2': 'value0-2'}, {'sub1': 'value1-1'}],
              'para2': [{'sub1': 'value2-1'}, {'sub1': 'value2-2'}],
              'para3': 'value3'}
    """
    result = {}

    for param_name, value in param_dit.items():
        param_parts = param_name.split('/')
        if len(param_parts) == 1:
            result[param_parts[0]] = value
        else:
            if param_parts[0] not in result:
                result[param_parts[0]] = []
            if len(result[param_parts[0]]) <= int(param_parts[1]):
                result[param_parts[0]].append({})
            result[param_parts[0]][int(param_parts[1])][param_parts[2]] = value

    return json.dumps(result)


def delta_params_data_to_provision_delta_plan_req_body(delta_data_list):
    all_provision_req_body = []
    for mo_param in delta_data_list:
        provision_req_body = {}

        operation_type = mo_param[-1]
        if operation_type == 'replace':
            operation_type = 'update'
        if operation_type == 'add':
            operation_type = 'create'
        if operation_type == 'remove':
            operation_type = 'delete'

        provision_req_body['operation_type'] = operation_type
        provision_req_body['dist_name'] = mo_param[0]
        provision_req_body['class_name'] = mo_param[0].split('/')[-1].split('-')[0]

        # TODO: if the operation is delete, actually no need to give {parameter_name: parameter_value},
        #       delta_data_list can be give like [['mo_dn', 'delete']], the provision api request body will be
        #       [{'operation_type':'delete', 'dist_name':'mo_dn', 'class_name':'class_name', 'payload':'{}'}]
        #       WAITING FOR VERIFICATION!!
        #       max_occurs needs to be added.
        if isinstance(mo_param[1], dict):
            provision_req_body['payload'] = convert_parameters_to_provision_delta_plan_payload(mo_param[1])
        else:
            provision_req_body['payload'] = {}

        all_provision_req_body.append(provision_req_body)
    return all_provision_req_body


def construct_delta_data_for_delta_commissioning(mo_dn, operation_type, **kwargs):
    delta_param_dict = {}
    for param_name, param_value in kwargs.items():
        param_name = param_name.replace('-', '/')
        delta_param_dict[param_name] = param_value
    return [mo_dn, delta_param_dict, operation_type]


def yaml_file_to_dictionary_info(file_path):
    """Get dictionary according yaml format file.

    | Input Parameters | Man. | Description |
    | file_path       | Yes  | file_path of yaml file |

    *RETURN VALUE*
    Dictionary of content

    Example
    | ${dictionary_content} | yaml_file_to_dictionary_info | /home/ute/a.yaml |
    """
    with open(file_path) as stream:
        NoDatesSafeLoader = yaml.SafeLoader
        NoDatesSafeLoader.yaml_implicit_resolvers = {
            k: [r for r in v if r[0] != 'tag:yaml.org,2002:timestamp']
            for k, v in NoDatesSafeLoader.yaml_implicit_resolvers.items()
        }
        data_loaded = yaml.load(stream, Loader=NoDatesSafeLoader)
    return data_loaded


def get_unique_id_string(prefix="", suffix="", precise="HIGH"):
    """This function is used to get unique id for connecting vdu, vcu, fhgw.

    :param str prefix: the prefix for the unique id.
    :param str suffix: the supffix for the unique id.
    :param str precise: the precision of the unique id, available value is HIGH, LOW, FORMAT_DATETIME,
                          HIGH_WITH_FORMAT_DATETIME_EPOCH, default is HIGH.
                          If precision is HIGH, will return a random string, which including string and number;
                          If precise is LOW, will return a random string, which only including number;
                          If precise is FORMAT_DATETIME, will return time string;
                          If precise is HIGH_WITH_FORMAT_DATETIME_EPOCH, will return a string including random char and time sting.

    :return str: unique_id
    """
    precise = precise.upper()
    if precise == "HIGH":
        rtn = _get_unique_id_high_precise(prefix, suffix)
    elif precise == "LOW":
        rtn = _get_unique_id_low_precise(prefix, suffix)
    elif precise == "FORMAT_DATETIME":
        rtn = _get_unique_id_datetime_precise(prefix, suffix)
    elif precise == "HIGH_WITH_FORMAT_DATETIME_EPOCH":
        rtn = _get_unique_id_datetime_precise_epoch(prefix, suffix)
    else:
        raise RuntimeError("Unknown precise:{}!!".format(precise))
    return rtn


def _get_unique_id_high_precise(prefix="", suffix=""):
    rtn = str(uuid.uuid4())
    rtn = rtn.replace('-', '')
    rtn = "{}{}{}".format(prefix, rtn, suffix)
    return rtn


def _get_unique_id_low_precise(prefix="", suffix=""):
    rtn = str(time.time())
    rtn = rtn.replace('.', '')
    rtn = "{}{}{}".format(prefix, rtn, suffix)
    return rtn


def _get_unique_id_datetime_precise(prefix="", suffix=""):
    unique_id_part1 = time.strftime("%Y%m%d_%H%M%S", time.localtime())

    unique_id_part2 = str(time.time())
    unique_id_part2 = unique_id_part2.split(".")[-1]

    unique_id = "{}_{}".format(unique_id_part1, unique_id_part2)
    rtn = "{}{}{}".format(prefix, unique_id, suffix)
    return rtn


def _get_unique_id_datetime_precise_epoch(prefix="", suffix=""):
    unique_id_part1 = str(uuid.uuid4())
    unique_id_part1 = unique_id_part1.replace('-', '')

    unique_id_part2 = time.strftime("%Y%m%d_%H%M%S", time.localtime())

    unique_id = "{}_{}".format(unique_id_part1, unique_id_part2)

    rtn = "{}{}{}".format(prefix, unique_id, suffix)
    return rtn


def member_should_not_contain(condition_key, condition_value, info_list, log_level="DEBUG", **kwargs):
    """Assert desired value appears in dict_list structure

    | Input Parameters | Man. | Description |
    | condition_key  | Yes | query condition, please see 'RMOD Status Should Be As Expected' |
    | condition_value | Yes | query condition, please see 'RMOD Status Should Be As Expected' |
    | info_list | Yes | information where value will be searched, type is list, member is dictionary |
    |           |      | [<dictionary1>, <dictionary2>, <dictionary3>, ... ]     |
    | log_level | No   | default value is DEBUG |
    | kwargs    | No   | kwargs, searched value is defined here |

    *RETURN VALUE*
    If value is matched, return False, otherwise return True

    Example
    | VDU Rest Login |                    |
    | ${rmods_info} | vdu.Get_Rmods_Status |
    | It will assert rmod_id='3' and availability_status='on line' and operational_state='enabled' |
    | generic_utils.member_should_not_contain |
    | ... |  condition_key=id  condition_value=3 | info_list=${rmods_info} | log_level=DEBUG |
    | ... | availability_status=on line | operational_state=enabled |
    """
    unexpected = False
    condition_match_flag = 0
    for info in info_list:
        if condition_value == info[condition_key]:
            condition_match_flag = 1
            for key, value in kwargs.items():
                if value is None:
                    continue
                try:
                    if info[key] != value:
                        raise AssertionError(
                            "{log_head} The {cond_key}={cond_val}->{values},expted:{expted}, act:{actual} {log_end}".format(
                                log_head=LOG_HEAD,
                                cond_key=condition_key,
                                cond_val=condition_value,
                                values=info[condition_key],
                                expted=value,
                                actual=info[key],
                                log_end=LOG_END,
                            )
                        )
                except AssertionError as e:
                    if log_level == "ERROR":
                        logger.error(str(e))
                    else:
                        logger.debug(str(e))
                    unexpected = True
                    continue
    unexpected = unexpected if condition_match_flag == 1 else True
    return unexpected


def convert_specific_format_string_to_list(input_data):
    """
    convert the input format like '34|45|656', '34,45,656' or '34;45;656'  to ['34', '45', '656']
    *AUTHOR* unknown
        history change, <date>,<who>,<what and how>
        -18.12.2023,chris.l.cao@nokia-sbell.com, 1.change to 'isinstance(input_data, list):'
                                                 2.change 'return input' to 'return input_data'
    """
    # if type(input_data) == list:
    if isinstance(input_data, list):
        return input_data
    else:
        return re.split('[|,;]', input_data)


def generate_log_path_with_log_type(log_type=''):
    """Generate case log path which is constructed with robot log output directory, test name, log type and timestamp.
    e.g,
    /home/ute/logs/TESTCASE__Test_RFRF/fhgw_snapshot/2023_01_11_05_44_15/Snapshot_FHGW-10714_controller_FHGW23R1_009.1.7_238c37a_2023-01-11T12_42_30.tar
     """
    output_dir = builtin_obj.get_variable_value("${OUTPUT_DIR}")
    logger.info("{} output_dir:{} {}".format(LOG_HEAD, output_dir, LOG_END))

    test_name = builtin_obj.get_variable_value("${TEST_NAME}")
    timestamp = builtin_obj.get_time()

    if test_name:
        log_path_without_suite_name = os.path.join("TESTCASE__" + str(test_name), log_type, timestamp)
    else:
        log_path_without_suite_name = os.path.join(log_type, timestamp)

    log_path_without_suite_name = log_path_without_suite_name.replace(" ", "_").replace(":", "_").replace("-", "_")
    log_path = os.path.join(output_dir, log_path_without_suite_name)

    if not os.path.exists(log_path):
        os.makedirs(log_path)
    return log_path
